import{_ as e,a0 as i,w as o,s as p,ao as m,I as s,x as a,a1 as n,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const R=JSON.parse('{"title":"Richard Stallman 正在与癌症作战 | LCTT x X-CMD","titleTemplate":false,"description":"Richard Stallman 正在与癌症作战 | LCTT (202310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Richard Stallman 正在与癌症作战 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Richard Stallman 正在与癌症作战 | LCTT (202310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202310/20230929 Richard Stallman is Battling Cancer ","title":"Richard Stallman 正在与癌症作战","tag":"202310","desc":""},"relativePath":"202310/20230929 Richard Stallman is Battling Cancer .md","filePath":"[post].md"}'),d={name:"202310/20230929 Richard Stallman is Battling Cancer .md"};function u(h,t,g,f,S,T){const r=i("Link");return o(),p("div",null,[t[15]||(t[15]=m('<h1 id="richard-stallman-正在与癌症作战" tabindex="-1">Richard Stallman 正在与癌症作战 <a class="header-anchor" href="#richard-stallman-正在与癌症作战" aria-label="Permalink to “Richard Stallman 正在与癌症作战”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202310/01/163837j5enqwi9a2h6v22e.jpg" alt=""></p><blockquote><p>让我们共同祈愿他早日康复！</p></blockquote><p>为了纪念 GNU 项目成立 40 周年，自由软件基金会（FSF）已计划在 <strong>10 月 1 日</strong>（即GNU 40）为家庭、学生以及美国的其他人群组织一场黑客马拉松活动。</p><p>活动之前，GNU 项目于 9 月 27 日迎来了 40 岁生日，Richard Stallman 和一些社区成员在瑞士<ruby>比尔<rt>Biel</rt></ruby>举行了 <ruby>GNU 黑客会议<rt>GNU Hacker&#39;s Meeting</rt></ruby>。</p><p>在会议上，他分享了自己的见解，并公开了自己正在与癌症作战的事实。</p><p>在主题演讲中，我们看到 <strong>Richard Stallman 已经没有他标志性的长胡子和长发，外貌发生了变化</strong>。他正在接受化疗以对抗癌症，这就能解释这一切。</p><p><img src="https://news.itsfoss.com/content/images/2023/09/richard-stallman-gnu-40.jpg" alt="Richard Stallman 在 GNU 黑客会议上（比尔，瑞士） | 源自：GNU.org"></p><p>他对自己的健康状况并没有多做说明，只是说病情是可以控制的，他仍能活很多年。</p><p>他特别强调：</p><blockquote><p>因此，这一点基本上改变了我的生活方式……我仍在为自由软件基金会和其他的事业持续工作。</p></blockquote><h3 id="richard-matthew-stallman-rms-愿你早日康复" tabindex="-1">Richard Matthew Stallman（RMS）：愿你早日康复！ <a class="header-anchor" href="#richard-matthew-stallman-rms-愿你早日康复" aria-label="Permalink to “Richard Matthew Stallman（RMS）：愿你早日康复！”">​</a></h3><p>Richard Stallman 是一位计算机科学家，他在 <strong>1983 年 9 月 27 日</strong>公布了名为 <strong>GNU</strong>（GNU&#39;s Not Unix）的类 Unix 操作系统。</p><p>因此，如果没有它，Linux 就无从谈起。这也是为何有些人更倾向于用 GNU/Linux 来称呼 Linux 的原因。</p><p>值得一提的是，他还创立了 <ruby>自由软件运动<rt>Free Software Movement</rt></ruby>，这是如今开源实践的基石。</p><p>当然，他在许多事情上都表达了富有争议性的观点，但他在 Linux 和开源上的影响是巨大的！</p><p>毫无疑问，得知 Richard 患癌的消息令人难过。然而，尽管面临这样的困境，他以 70 岁的高龄仍然兴致勃勃地出现在了主题演讲中，并发表了演讲。</p><p>让我们祝愿 Richard 早日恢复！💐</p><hr>',19)),s("p",null,[t[1]||(t[1]=a("via: ",-1)),n(r,{href:"https://news.itsfoss.com/richard-stallman-battling-cancer/"},{default:l(()=>[...t[0]||(t[0]=[a("https://news.itsfoss.com/richard-stallman-battling-cancer/",-1)])]),_:1})]),s("p",null,[t[6]||(t[6]=a("作者：",-1)),n(r,{href:"https://news.itsfoss.com/author/ankush/"},{default:l(()=>[...t[2]||(t[2]=[a("Ankush Das",-1)])]),_:1}),t[7]||(t[7]=a(" 选题：",-1)),n(r,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[3]||(t[3]=[a("lujun9972",-1)])]),_:1}),t[8]||(t[8]=a(" 译者：",-1)),n(r,{href:"https://linux.cn/lctt/ChatGPT"},{default:l(()=>[...t[4]||(t[4]=[a("ChatGPT",-1)])]),_:1}),t[9]||(t[9]=a(" 校对：",-1)),n(r,{href:"https://github.com/wxy"},{default:l(()=>[...t[5]||(t[5]=[a("wxy",-1)])]),_:1})]),s("p",null,[t[12]||(t[12]=a("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[10]||(t[10]=[a("LCTT",-1)])]),_:1}),t[13]||(t[13]=a(" 原创编译，",-1)),n(r,{href:"https://linux.cn/"},{default:l(()=>[...t[11]||(t[11]=[a("Linux中国",-1)])]),_:1}),t[14]||(t[14]=a(" 荣誉推出",-1))])])}const c=e(d,[["render",u]]);export{R as __pageData,c as default};
